WITH valid AS (SELECT *, CAST(budget AS INT) budget_int FROM departments WHERE budget BETWEEN 2334000 AND 3845000) SELECT id, dept_name, location, budget_int, NTILE(4) OVER (PARTITION BY dept_name ORDER BY budget DESC, id) budget_bucket, LAST_VALUE(location, TRUE) OVER w_recent last_known_location, SUM(budget_int) OVER w_hist running_budget_int, AVG(budget_int) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) budget_int_avg_5 FROM valid WINDOW w_recent AS (PARTITION BY dept_name, location ORDER BY budget_int, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_hist AS (ORDER BY budget_int, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
